        getPerformanceSummary(history) {
            if (!history.length) return {};
            var finalState = history[history.length - 1];
            var results = finalState.results || {};
            var totalNIs = history.map(function(h) { return (h.results && h.results.totalNI) || 0; });
            var avgNI = totalNIs.reduce(function(s, v) { return s + v; }, 0) / totalNIs.length;

            /* CBVI Calculation */
            var startTBVPS = 8.50;
            var endTBVPS = results.tbvps || startTBVPS;
            var tbvpsGrowth = (endTBVPS - startTBVPS) / startTBVPS;
            var roe = (results.roe || 0) / 100;
            var tier1 = (results.tier1Ratio || 0) / 100;
            var cir = (results.cir || 0) / 100;
            var lossRatio = (results.loanLossRatio || 0) / 100;
            var pb = results.pb || 0.5;

            var cbvi = 0;
            cbvi += Math.min(tbvpsGrowth / 0.36, 1) * 25;
            cbvi += Math.min(roe / 0.15, 1) * 20;
            if (tier1 >= 0.10 && tier1 <= 0.14) cbvi += 15;
            else if (tier1 > 0.14) cbvi += 10;
            else cbvi += 0;
            cbvi += Math.max(0, (0.07 - Math.abs(roe * 0.04 - cir * 0.01))) * 15 / 0.07;
            cbvi += Math.max(0, 1 - cir / 0.70) * 12;
            cbvi += Math.max(0, 1 - lossRatio / 0.04) * 8;
            cbvi += Math.min(pb / 1.5, 1) * 5;

            /* Penalties */
            if (tier1 < 0.10) cbvi -= 10;
            if (tier1 > 0.14) cbvi -= 5;
            if (roe < 0.08) cbvi -= 15;

            cbvi = Math.max(0, Math.min(100, Math.round(cbvi)));

            var performance = window.mySimulation.t('perf_needs_improvement');
            if (cbvi >= 75) performance = window.mySimulation.t('perf_excellent');
            else if (cbvi >= 60) performance = window.mySimulation.t('perf_good');
            else if (cbvi >= 45) performance = window.mySimulation.t('perf_adequate');

            var insights = [];
            if (roe > 0.12) insights.push(window.mySimulation.t('insight_roe_strong'));
            if (roe <= 0.08) insights.push(window.mySimulation.t('insight_roe_weak'));
            if (tier1 < 0.10) insights.push(window.mySimulation.t('insight_tier1_low'));
            if (tier1 > 0.14) insights.push(window.mySimulation.t('insight_tier1_high'));
            if (cir < 0.55) insights.push(window.mySimulation.t('insight_cir_good'));
            if (cir > 0.65) insights.push(window.mySimulation.t('insight_cir_high'));
            if (lossRatio > 0.03) insights.push(window.mySimulation.t('insight_losses_high'));
            if (pb > 1.2) insights.push(window.mySimulation.t('insight_pb_premium'));
            if (pb < 0.8) insights.push(window.mySimulation.t('insight_pb_discount'));

            return {
                cbvi: cbvi,
                performance: performance,
                tbvpsGrowth: Math.round(tbvpsGrowth * 1000) / 10,
                finalROE: results.roe,
                finalTier1: results.tier1Ratio,
                finalCIR: results.cir,
                finalPB: results.pb,
                avgNetIncome: Math.round(avgNI),
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.tier1Ratio < 10.0) return window.mySimulation.t('hint_capital_low');
            if (results.roe < 8.0) return window.mySimulation.t('hint_roe_low');
            if (results.loanLossRatio > 3.0) return window.mySimulation.t('hint_losses_high');
            if (results.cir > 60) return window.mySimulation.t('hint_cir_high');
            if (results.roe > 14.0 && results.tier1Ratio > 11.0) return window.mySimulation.t('hint_strong');
            return null;
        }

