                    insight_roe_weak:    'El ROE está por debajo del costo de capital — el banco está destruyendo valor para los accionistas.',
                    insight_tier1_low:   'El ratio de capital está por debajo del mínimo regulatorio — el banco enfrenta acción de los supervisores.',
                    insight_tier1_high:  'La sobrecapitalización puede indicar oportunidades de crecimiento perdidas o un conservadurismo excesivo.',
                    insight_cir_good:    'Excelente eficiencia de costos — la inversión tecnológica está dando resultado.',
                    insight_cir_high:    'El ratio de eficiencia es elevado — la transformación de la banca minorista debería ser una prioridad.',
                    insight_losses_high: 'Las pérdidas crediticias están elevadas — la gestión del riesgo de crédito necesita atención.',
                    insight_pb_premium:  'La prima de precio sobre valor libros refleja la confianza del mercado en la gestión.',
                    insight_pb_discount: 'Cotiza por debajo del valor libros — el mercado duda de la rentabilidad futura.'
                }
            };
        }

        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var briefEl = document.getElementById('briefingText');
            var panel = document.getElementById('briefingPanel');
            var iconEl = document.getElementById('briefingIcon');
            var rateEl = document.getElementById('baseRateDisplay');

            var lang = 'en';
            try { lang = window.mySimulation && window.mySimulation.lang ? window.mySimulation.lang : 'en'; } catch(e) {}
            var desc = lang === 'es' ? round.description_es : round.description_en;

            if (briefEl) briefEl.innerHTML = desc;
            if (iconEl) iconEl.textContent = round.icon;
            if (rateEl) rateEl.textContent = round.baseRate.toFixed(1) + '%';

            if (panel) {
                if (idx === 1) {
                    panel.classList.add('bank072-shock');
                } else {
                    panel.classList.remove('bank072-shock');
                }
            }
        }
    }

    document.addEventListener('DOMContentLoaded', function() {
        window.mySimulation = new USF.SimulationFramework();
        window.mySimulation.initialize(new BankAdapter(), {
            simulationType: 'universal_banking_072',
            maxPeriods: 3,
            autoSaveInterval: 30000
        });
    });

})();
